pub(crate) fn retry_observation<T>(
    sleeper: &dyn Sleeper,
    attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
) -> Result<T, GraphError> {
    retry_observation_within(sleeper, None, attempt)
}

