604	/// The other members of `package`'s fixed group that keep a changelog, with the name each is shown by in release notes.
605	fn fixed_group_changelogs<'w, R: CommandRunner, D: DependencyResolver>(
606	    workspace: &'w Workspace<'_, R, D>,
607	    package: &callisto_model::Package,
608	) -> Vec<(String, &'w std::path::Path)> {
609	    let groups = &workspace.config.groups;
610	    let Some(group) = groups.fixed_of.get(&package.id) else {
611	        return Vec::new();
612	    };
613	    workspace
614	        .graph
615	        .packages()
616	        .filter(|member| member.id != package.id && groups.fixed_of.get(&member.id) == Some(group))
617	        .filter_map(|member| Some((member.canonical_id().to_string(), member.changelog.as_deref()?)))
618	        .collect()
619	}
