621	fn add_forge_releases<R: CommandRunner, D: DependencyResolver>(
622	    workspace: &Workspace<'_, R, D>,
623	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
624	    owners: &Owners,
625	    ops: &mut Ops,
626	) -> Result<(), GraphError> {
627	    let Ops {
628	        operations,
629	        prepared,
630	        index: OpIndex {
631	            tag_by_package,
632	            forge_by_package,
633	            ..
634	        },
635	        ..
636	    } = ops;
637	
638	    for (id, (package, version)) in owned(selected, owners) {
639	        if package
640	            .publish_to
641	            .iter()
642	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
643	        {
644	            let tag = tag_by_package.get(id).expect("release point has tag").clone();
645	            let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])?;
646	            let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
647	                Some(PreparedOperation::Tag(prepared_tag)) => prepared_tag.name.clone(),
648	                _ => {
649	                    return Err(GraphError::ReleaseInvariant {
650	                        detail: format!(
651	                            "forge release `{:?}` prerequisite is not a prepared Tag operation",
652	                            operation.id()
653	                        ),
654	                    })
655	                }
656	            };
657	            prepared.insert(
658	                operation.id().clone(),
659	                PreparedOperation::ForgeRelease(ForgeReleaseOperation {
660	                    tag,
661	                    prerelease: version.is_prerelease(),
662	                    notes: group_release_notes(
663	                        &workspace.root,
664	                        package.changelog.as_deref(),
665	                        &fixed_group_changelogs(workspace, package),
666	                        version,
667	                    )?,
668	                }),
669	            );
670	            forge_by_package.insert(id.clone(), operation.id().clone());
671	            operations.insert(operation.id().clone(), operation);
672	        }
673	    }
674	    Ok(())
675	}
