249	/// A timed-out `gh attestation verify` is a transient observation, not a hard failure that aborts the release.
250	fn attempt_attestation_verify<R: CommandRunner>(
251	    runner: &R,
252	    args: &[&str],
253	    cwd: &Path,
254	) -> Result<Attempt<bool>, GraphError> {
255	    let observed = match run_observation(runner, programs::GH, args, cwd, timeouts::ATTESTATION_VERIFY, false)? {
256	        Ok(output) => output,
257	        Err(_unavailable) => {
258	            return Ok(Attempt::Transient {
259	                value: false,
260	                retry_after: None,
261	            })
262	        }
263	    };
264	    Ok(Attempt::Settled(observed.success()))
265	}
