pub struct ValidationConfig {
    pub allow_empty_changesets: bool,
}

#[derive(Clone, Debug)]
pub struct RegistryConfig {
    pub kind: Ecosystem,
    pub url: Option<String>,
    /// Upload endpoint of a `pypi` registry whose index (`url`) is not also where files are uploaded.
    pub publish_url: Option<String>,
    /// How long a version this run published may take to appear; `None` is the ecosystem's default.
    pub confirm_timeout: Option<std::time::Duration>,
    /// The longest one publish command may run; `None` is the default of 15 minutes.
    pub publish_timeout: Option<std::time::Duration>,
}

/// One declared release artifact. `target` is opaque -- Callisto passes it to
/// whatever builds the bytes and never parses it -- and `asset_name` is the
/// externally stable name the artifact is published under.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductArtifactConfig {
    /// The package whose build produces these bytes. Need not be the product.
    pub package: PackageId,
    pub target: String,
    pub asset_name: String,
}

/// Both `product-package` and every `[[release.artifact]] package` must name one
/// ecosystem-qualified identity; one parser so the two cannot drift.
fn parse_qualified_package(value: &str, key: &str) -> Result<PackageId, ConfigError> {
    ConfigError::require_qualified(value, key)?;
    PackageId::parse(value).map_err(|_error| ConfigError::InvalidProductRelease {
        detail: format!("{key} must be an ecosystem-qualified package identity"),
    })
}

fn resolve_product_release(raw: RawProductReleaseConfig) -> Result<ProductReleaseConfig, ConfigError> {
    let package = parse_qualified_package(&raw.product_package, "product-package")?;
    if raw.artifact.is_empty() {
        return Err(ConfigError::InvalidProductRelease {
            detail: "a [release] section must declare at least one [[release.artifact]]".to_owned(),
        });
    }
    let mut artifacts = Vec::with_capacity(raw.artifact.len());
    let mut seen_assets = BTreeSet::new();
    for entry in &raw.artifact {
        let package = parse_qualified_package(&entry.package, "[[release.artifact]] package")?;
        if !is_safe_artifact_component(&entry.target) || !is_safe_artifact_component(&entry.asset_name) {
            return Err(ConfigError::InvalidProductRelease {
                detail: format!(
                    "artifact target `{}` and asset-name `{}` must each be a single safe path component",
                    entry.target, entry.asset_name
                ),
            });
        }
        if !seen_assets.insert(entry.asset_name.clone()) {
            return Err(ConfigError::InvalidProductRelease {
                detail: format!("asset-name `{}` is declared more than once", entry.asset_name),
            });
        }
        artifacts.push(ProductArtifactConfig {
            package,
            target: entry.target.clone(),
            asset_name: entry.asset_name.clone(),
        });
    }
    let forge_repository = raw
        .forge_repository
        .clone()
        .map(|raw| {
            GitHubRepository::parse(&raw).map_err(|error| ConfigError::InvalidProductRelease {
                detail: format!("forge-repository `{raw}` is invalid: {error}"),
            })
        })
        .transpose()?;
    Ok(ProductReleaseConfig {
        package,
        artifacts,
        forge_repository,
    })
}

/// Per-package overrides from a `[[package]]` block in `callisto.toml`.
///
/// Every field is `Option<T>` — `None` means "not specified; use the package's default."
/// Only fields that the user explicitly set in the `[[package]]` block are `Some`.
#[derive(Clone, Debug)]
pub struct PackageConfig {
    pub release_trigger: Option<ReleaseTrigger>,
    pub publish_to: Option<Vec<PublishTarget>>,
    pub tag_template: Option<TagTemplate>,
    /// Consulted for the last tag only after `tag_template` finds none.
    pub previous_tag_templates: Vec<TagTemplate>,
    /// Changelog path relative to the package's own root directory.
    pub changelog: Option<PathBuf>,
    pub pre_major_inference: Option<PreMajorInferencePolicy>,
}

/// Pre-1.0 (`0.y.z`) severity-downgrade policy. A closed 3-state choice --
/// modeled as an enum rather than two independent bools so the type system
/// rules out the unreachable-via-parser 4th combination a `{breaking_to_minor:
/// false, feat_to_patch: true}`-shaped struct literal could otherwise
/// construct.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum PreMajorInferencePolicy {
    #[default]
    Off,
    /// Downgrades an inferred Major bump to Minor.
    Conservative,
    /// Downgrades an inferred Major bump to Minor, and Minor to Patch.

